{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C02"],
      "claim": "Compound 9q showed a brain/plasma ratio of 2.7 and CNS exposure equivalent to known sedating antihistamines after iv dosing, directly supporting meaningful BBB access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "PET imaging in baboons showed rapid brain localization of [18F]benperidol in dopaminergic receptor-rich regions, demonstrating in vivo BBB permeability in a primate species.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "In rats, [11C]SA4503 showed high brain uptake with 75-85% of total brain radioactivity being receptor-specific, indicating substantial CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Secondary amide analogue 14 showed a brain-to-blood ratio consistent with free passage across the BBB and a measured rat brain Cmax of 234 ng/g.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Acetamide analogue 10 showed a brain-to-blood ratio of 1.1 in rats, consistent with free passage across the blood-brain barrier.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "Multiple direct in vivo rodent and primate records demonstrate high brain/plasma ratios, substantial brain uptake, and CNS exposure consistent with meaningful BBB penetration; no contradictory evidence was present.",
  "evidence_gaps": [
    "No direct query-specific brain or plasma PK measurement is visible; prediction relies on close structural analogues.",
    "Unbound brain concentrations or CSF data are not reported, so total brain/plasma ratios may not fully define free brain exposure.",
    "Efflux transporter involvement was not explicitly assessed in the visible records."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

